const item = $input.first().json.body || $input.first().json;

const meetingId = item.meetingId || 'AGM-2026';
const meetingTitle = item.title || 'Annual General Meeting 2026';
const meetingDate = item.meetingDate || '2026-11-29 10:00 AM';
const totalEligibleOwners = Number(item.totalEligibleOwners || 320);
const statutoryQuorumPercent = Number(item.statutoryQuorumPercent || 33.3);
const confirmedPhysical = Number(item.confirmedPhysical || 45);
const confirmedVirtual = Number(item.confirmedVirtual || 55);
const proxyVotesReceived = Number(item.proxyVotesReceived || 12);
const towerBreakdown = item.towerBreakdown || [
  { tower: 'Tower A', confirmed: 35, total: 100 },
  { tower: 'Tower B', confirmed: 40, total: 100 },
  { tower: 'Tower C', confirmed: 25, total: 80 },
  { tower: 'Villas', confirmed: 12, total: 40 }
];

const totalAttending = confirmedPhysical + confirmedVirtual + proxyVotesReceived;
const requiredQuorumCount = Math.ceil((statutoryQuorumPercent / 100) * totalEligibleOwners);

const prompt = `You are the Official Legal & Governance Auditor for the Mana Residency Management Committee.
Audit the following General Body Assembly attendee count for quorum compliance under State Apartment Ownership bylaws:

Assembly Dossier:
- Meeting: ${meetingTitle} (${meetingId}) on ${meetingDate}
- Total Registered Flat Owners: ${totalEligibleOwners}
- Statutory Quorum Requirement: ${statutoryQuorumPercent}% (${requiredQuorumCount} owners required)
- Current Confirmations: Physical: ${confirmedPhysical}, Virtual: ${confirmedVirtual}, Proxies: ${proxyVotesReceived}
- Total Present / Confirmed: ${totalAttending}
- Tower Breakdown: ${JSON.stringify(towerBreakdown)}

Audit Tasks:
1. Determine quorumStatus: "QUORUM_MET" | "NEAR_QUORUM" (within 10%) | "QUORUM_DEFICIT".
2. Calculate shortfall (number of owners needed to achieve legal quorum).
3. Identify low-turnout clusters/towers.
4. Formulate an adjournment risk advisory (e.g. 30-min adjournment procedure per bylaws).
5. Generate an urgent, professional WhatsApp notification bulletin ready to broadcast with emojis.

Respond ONLY with a valid JSON object matching this schema:
{
  "quorumStatus": "QUORUM_MET" | "NEAR_QUORUM" | "QUORUM_DEFICIT",
  "quorumPercentageCurrent": number,
  "statutoryQuorumRequired": number,
  "attendeesCount": number,
  "shortfall": number,
  "adjournmentRisk": "NONE" | "LOW" | "HIGH" | "CRITICAL",
  "towerOutreachTargets": [
    { "tower": string, "shortfallNotes": string, "recommendedAction": string }
  ],
  "governanceVerdict": string,
  "whatsappBroadcastBulletin": string
}`;

return [{ json: { prompt, meetingId, meetingTitle, totalAttending, requiredQuorumCount } }];

const gemini = $input.first().json;
let parsed = {};
try {
  const raw = gemini.candidates[0].content.parts[0].text;
  parsed = JSON.parse(raw);
} catch (e) {
  const meta = $('Prepare AI Prompt').first().json;
  const isMet = meta.totalAttending >= meta.requiredQuorumCount;
  parsed = {
    quorumStatus: isMet ? "QUORUM_MET" : "QUORUM_DEFICIT",
    quorumPercentageCurrent: Math.round((meta.totalAttending / 320) * 100),
    statutoryQuorumRequired: 33.3,
    attendeesCount: meta.totalAttending,
    shortfall: Math.max(0, meta.requiredQuorumCount - meta.totalAttending),
    adjournmentRisk: isMet ? "NONE" : "HIGH",
    towerOutreachTargets: [{ tower: "All Towers", shortfallNotes: "Attendance below 33% threshold", recommendedAction: "Door-to-door steward reminder" }],
    governanceVerdict: isMet ? "Statutory quorum successfully achieved." : "Quorum not yet met. Active mobilization required.",
    whatsappBroadcastBulletin: "📢 *URGENT AGM NOTICE*\nQuorum count is currently at " + meta.totalAttending + ". Please confirm your presence to avoid meeting adjournment!"
  };
}

const meta = $('Prepare AI Prompt').first().json;
return [{ json: { status: "success", meetingId: meta.meetingId, title: meta.meetingTitle, auditedAt: new Date().toISOString(), evaluation: parsed } }];
